import { expect, it, describe } from 'vitest';
import type { IncomingMessage, OutgoingMessage, ListSessionsMessage, SessionListMessage } from './messages.js';

describe('Message Types', () => {
  it('includes ListSessionsMessage in IncomingMessage', () => {
    const msg: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {
        sessionId: 's1',
        updatedAt: '2026-01-01T00:00:00Z'
      }
    };
    expect(msg.type).toBe('list_sessions');
  });

  it('includes SessionListMessage in OutgoingMessage', () => {
    const msg: OutgoingMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00Z',
          updatedAt: '2026-01-01T00:00:00Z',
          entryCount: 1
        }
      ]
    };
    expect(msg.type).toBe('session_list');
  });
});

